    @Override protected void startUp() throws IOException
    {
        ledger = new LedgerStore(gson, getPluginDirectory());
        ledger.load();
        supplies = new WaveSupplyTracker(itemManager, (wave, cost, detail) -> {
            if (cost > 0) record(LedgerEvent.Type.SUPPLIES, -cost, detail, wave);
        }, this::refreshSuppliesOnly);
        panel = new FortisProfitPanel(this);
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setColor(new Color(198, 149, 59));
        graphics.fillRoundRect(1, 1, 14, 14, 4, 4);
        graphics.setColor(Color.BLACK);
        graphics.setFont(new Font("SansSerif", Font.BOLD, 12));
        graphics.drawString("F", 4, 12);
        graphics.dispose();
        navigation = NavigationButton.builder().tooltip("Colosseum Profit Tracker")
            .icon(image).priority(6).panel(panel).build();
        toolbar.addNavigation(navigation);
        refresh();
    }

    @Override protected void shutDown()
    {
        if (navigation != null) toolbar.removeNavigation(navigation);
        if (panel != null) panel.stopUpdates();
        // Do not write unfinalized supply deductions when shutting down mid-attempt.
        if (supplies != null) supplies.reset();
    }

    /** The exact Sol Heredit icon used by RuneLite's HiScores panel. */
    void loadSolHereditIcon(Consumer<BufferedImage> callback)
    {
        spriteManager.getSpriteAsync(HiscoreSkill.SOL_HEREDIT.getSpriteId(), 0, callback);
    }

    String account()
    {
        return client.getLocalPlayer() == null ? "Unknown" : client.getLocalPlayer().getName();
    }

    private void checkAccount()
    {
        String current = account();
        // Client.getLocalPlayer() can briefly be null during transitions; do not
        // discard an already confirmed wave simply because the name is unavailable.
        if ("Unknown".equals(current)) return;
        if (lastAccount == null || ( !"Unknown".equals(lastAccount) && !lastAccount.equals(current)))
        {
            if (supplies != null) supplies.reset();
            inColosseumLobby = false;
            lastLobbySeenMs = 0;
            active = false;
            terminal = false;
            exitHasLoot = false;
            activeWave = 0;
            completedWave = 0;
            lastExitWave = 0;
            lastConfirmedWave = 0;
            lastConfirmedWaveMs = 0;
            lastExitType = null;
            lastAccount = current;
        }
    }

    synchronized void record(LedgerEvent.Type type, long gp, String note, int wave)
    {
        ledger.add(new LedgerEvent(account(), type, gp, note, wave));
        refresh();
    }

    void delete(LedgerEvent event)
    {
        ledger.delete(event);
        refresh();
    }

    boolean editEntry(LedgerEvent event, LedgerEvent.Type type, long gp, int wave, String note)
    {
        boolean changed = ledger.update(event, type, gp, wave, note);
        if (changed) refresh();
        return changed;
    }

    boolean trackingSupplies() { return supplies != null && supplies.isTracking(); }
    long currentSupplyCost() { return supplies == null ? 0 : supplies.currentCost(); }
    java.util.List<WaveSupplyTracker.ItemUsage> currentSupplyItems()
    {
        return supplies == null ? java.util.Collections.emptyList() : supplies.currentItems();
    }
    net.runelite.client.util.AsyncBufferedImage supplyIcon(int itemId)
    {
        return itemManager.getImage(itemId);
    }
    java.util.List<LedgerEvent> entries() { return ledger.list(); }

    /** Explicit disk reload; never discard a live run's unsaved supplies. */
    int reloadLedgerFromDisk()
    {
        if (active || trackingSupplies())
        {
            throw new IllegalStateException("Finish or leave the current Colosseum attempt before reloading the ledger.");
        }
        // A successful parse replaces all in-memory entries atomically.
        return ledger.reload();
    }


    private void refresh()
    {
        if (panel == null || !refreshQueued.compareAndSet(false, true)) return;
        SwingUtilities.invokeLater(() ->
        {
            refreshQueued.set(false);
            if (panel != null) panel.refresh();
        });
    }

    /** Supply updates do not change the persisted ledger or history tables. */
    private void refreshSuppliesOnly()
    {
        if (panel == null || !suppliesRefreshQueued.compareAndSet(false, true)) return;
        SwingUtilities.invokeLater(() ->
        {
            suppliesRefreshQueued.set(false);
            if (panel != null) panel.refreshSuppliesOnly();
        });
    }

    /** ItemManager must be accessed on RuneLite's client thread, not Swing's EDT. */
    void requestQuiverTurnInValue(java.util.function.LongConsumer onValue)
    {
        clientThread.invokeLater(() ->
        {
            long unitPrice = itemManager.getItemPrice(28924); // Sunfire splinters
            long value = unitPrice > 0 ? unitPrice * 4_000L : 0L;
            SwingUtilities.invokeLater(() -> onValue.accept(value));
        });
    }

    void recordQuiverTurnIn(long gp, long unitPrice)
    {
        if (gp <= 0 || unitPrice <= 0 || gp != unitPrice * 4_000L)
        {
            throw new IllegalArgumentException("Invalid quiver exchange valuation");
        }
        record(LedgerEvent.Type.ADJUSTMENT, gp,
            "Dizana's quiver exchanged for 4,000 Sunfire splinters @ " + unitPrice + " GP each", -1);
    }

    /** Track pre-wave supplies only while Minimus is present in the Colosseum lobby.
     * Combat supply tracking continues only during a known Colosseum run in the arena.
     * Leaving the area abandons unfinalized consumption so no outside use is charged.
     */
    @Subscribe public void onGameTick(GameTick event)
    {
        if (supplies == null) return;
        if (!config.autoSupplyTracking() || client.getGameState() != GameState.LOGGED_IN)
        {
            supplies.reset();
            inColosseumLobby = false;
            ayakNormalWasFrameZero = false;
            blowpipeWasFrameZero = false;
            return;
        }
        inColosseumLobby = isColosseumLobby();
        long now = System.currentTimeMillis();
        if (inColosseumLobby) lastLobbySeenMs = now;
        boolean inArenaRun = active && !terminal && client.isInInstancedRegion();
        // The lobby disappears before the first wave-start message arrives.
        // Preserve its accrued costs during that brief transition, without
        // tracking inventory changes until the Colosseum run is confirmed.
        boolean enteringArena = !active && supplies.isTracking() && client.isInInstancedRegion()
            && lastLobbySeenMs > 0 && now - lastLobbySeenMs <= 30_000L;
        if (!inColosseumLobby && !inArenaRun && !enteringArena)
        {
            supplies.reset();
            ayakNormalWasFrameZero = false;
            blowpipeWasFrameZero = false;
            return;
        }
        if (inColosseumLobby && !active && !supplies.isTracking())
        {
            // -1 is the existing "Adj." wave marker; the note says "pre-wave lobby".
            supplies.begin(-1, client.getItemContainer(InventoryID.INVENTORY),
                client.getItemContainer(InventoryID.EQUIPMENT));
            supplies.snapshotQuiver(client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO),
                client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT));
        }
        updateRunePouchSupplies();
        // Blowpipe uses internal darts and scales; no inventory stack shrinks.
        boolean blowpipeShot = inArenaRun && supplies.isTracking() && isBlowpipeEquipped()
            && client.getLocalPlayer() != null
            && client.getLocalPlayer().getAnimation() == BLOWPIPE_ATTACK_ANIMATION
            && client.getLocalPlayer().getAnimationFrame() == 0;
        if (blowpipeShot && !blowpipeWasFrameZero)
        {
            supplies.blowpipeShot(dartLossRate());
        }
        blowpipeWasFrameZero = blowpipeShot;
        // Run-level cost: normal Ayak attacks are sampled once at frame zero.
        // Do not count the same zero frame twice if it persists across ticks.
        boolean normal = inArenaRun && supplies.isTracking() && isAyakEquipped()
            && client.getLocalPlayer() != null
            && client.getLocalPlayer().getAnimation() == AYAK_CAST_ANIMATION
            && client.getLocalPlayer().getAnimationFrame() == 0;
        if (normal && !ayakNormalWasFrameZero) supplies.ayakCast();
        ayakNormalWasFrameZero = normal;
    }

    @Subscribe public void onAnimationChanged(AnimationChanged event)
    {
        if (event.getActor() != client.getLocalPlayer() || !active || terminal
            || !client.isInInstancedRegion() || supplies == null || !supplies.isTracking()) return;
        int animation = event.getActor().getAnimation();
        if (animation == AYAK_SPECIAL_ANIMATION && isAyakEquipped())
        {
            supplies.ayakCast();
        }
        else if (animation == SCYTHE_ATTACK_ANIMATION && isChargedScytheEquipped())
        {
            supplies.scytheAttack();
        }
        else if (animation == SHADOW_CAST_ANIMATION && isChargedShadowEquipped())
        {
            supplies.shadowCast();
        }
        else if (animation == VENATOR_BOW_ATTACK_ANIMATION && isChargedVenatorBowEquipped())
        {
            supplies.venatorBowAttack();
        }
    }

    private int equippedWeaponId()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null || equipment.getItems().length <= 3) return -1;
        net.runelite.api.Item weapon = equipment.getItems()[3];
        return weapon == null ? -1 : weapon.getId();
    }

    private boolean isChargedScytheEquipped()
    {
        int id = equippedWeaponId();
        return id == ItemID.SCYTHE_OF_VITUR || id == ItemID.HOLY_SCYTHE_OF_VITUR
            || id == ItemID.SANGUINE_SCYTHE_OF_VITUR;
    }

    private boolean isChargedShadowEquipped()
    {
        return equippedWeaponId() == ItemID.TUMEKENS_SHADOW;
    }

    private boolean isChargedVenatorBowEquipped()
    {
        // The uncharged bow has a different item ID and must not incur essence costs.
        return equippedWeaponId() == ItemID.VENATOR_BOW;
    }

    private boolean isBlowpipeEquipped()
    {
        return equippedWeaponId() == ItemID.TOXIC_BLOWPIPE;
    }

    private double dartLossRate()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null) return 1.0;
        Item[] items = equipment.getItems();
        int capeSlot = EquipmentInventorySlot.CAPE.getSlotIdx();
        if (items.length <= capeSlot || items[capeSlot] == null || items[capeSlot].getId() <= 0)
            return 1.0;
        String name = itemManager.getItemComposition(items[capeSlot].getId())
            .getName().toLowerCase(Locale.ROOT);
        if (name.contains("assembler") || name.contains("dizana") || name.contains("quiver")) return 0.20;
        if (name.contains("accumulator") || name.contains("ranging cape") || name.contains("max cape")) return 0.28;
        if (name.contains("attractor")) return 0.40;
        return 1.0;
    }

    @Subscribe public void onVarbitChanged(VarbitChanged event)
    {
        if (!config.autoSupplyTracking() || supplies == null || !supplies.isTracking()
            || !(inColosseumLobby || (active && !terminal && client.isInInstancedRegion()))) return;
        int varpId = event.getVarpId();
        if (varpId != VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO
            && varpId != VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT) return;
        supplies.quiverChanged(client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO),
            client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT));
    }

    @Subscribe public void onProjectileMoved(ProjectileMoved event)
    {
        if (!active || terminal || !client.isInInstancedRegion() || supplies == null
            || !supplies.isTracking() || !isBlowpipeEquipped() || client.getLocalPlayer() == null
            || client.getLocalPlayer().getAnimation() != BLOWPIPE_ATTACK_ANIMATION) return;
        Projectile projectile = event.getProjectile();
        if (projectile == null || projectile == lastBlowpipeProjectile) return;
        int dart = dartForProjectile(projectile.getId());
        if (dart <= 0) return;
        WorldPoint from = WorldPoint.fromLocal(client,
            new LocalPoint(projectile.getX1(), projectile.getY1()));
        if (!client.getLocalPlayer().getWorldLocation().equals(from)) return;
        lastBlowpipeProjectile = projectile;
        supplies.blowpipeDartObserved(dart);
    }

    private static int dartForProjectile(int projectileId)
    {
        switch (projectileId)
        {
            case 226: return ItemID.BRONZE_DART;
            case 227: return ItemID.IRON_DART;
            case 228: return ItemID.STEEL_DART;
            case 32: return ItemID.BLACK_DART;
            case 229: return ItemID.MITHRIL_DART;
            case 230: return ItemID.ADAMANT_DART;
            case 231: return ItemID.RUNE_DART;
            case 1936: return ItemID.AMETHYST_DART;
            case 1122: return ItemID.DRAGON_DART;
            default: return -1;
        }
    }

    private boolean isAyakEquipped()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null || equipment.getItems().length <= 3) return false;
        net.runelite.api.Item weapon = equipment.getItems()[3];
        return weapon != null && weapon.getId() == ItemID.EYE_OF_AYAK;
    }

    private boolean isColosseumLobby()
    {
        // Minimus can also appear during an instanced run; that is not the lobby.
        if (client.isInInstancedRegion()) return false;
        for (NPC npc : client.getNpcs())
        {
            if (npc != null && npc.getId() == COLOSSEUM_LOBBY_MINIMUS_ID)
            {
                return true;
            }
        }
        return false;
    }

    @Subscribe public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (config.autoSupplyTracking() && supplies != null && supplies.isTracking()
            && (inColosseumLobby || (active && !terminal && client.isInInstancedRegion())))
        {
            supplies.onMenuOption(event.getMenuOption(), event.getItemId());
        }
    }

    @Subscribe public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (!config.autoSupplyTracking() || supplies == null || !supplies.isTracking()
            || !(inColosseumLobby || (active && !terminal && client.isInInstancedRegion()))) return;
        ItemContainer container = event.getItemContainer();
        if (container == null) return;
        if (container.getId() == InventoryID.INVENTORY.getId()) supplies.inventoryChanged(container);
        else if (container.getId() == InventoryID.EQUIPMENT.getId()) supplies.equipmentChanged(container);
    }

    private void startSuppliesIfNecessary(int wave)
    {
        if (!config.autoSupplyTracking() || supplies == null
            || !(inColosseumLobby || client.isInInstancedRegion())) return;
        if (!supplies.isTracking()) supplies.begin(wave, client.getItemContainer(InventoryID.INVENTORY),
            client.getItemContainer(InventoryID.EQUIPMENT));
        else supplies.changeWave(wave);
        supplies.snapshotQuiver(client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO),
            client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT));
    }

    /** Sync four rune pouch slots once per game tick while Colosseum tracking is active.
     * ItemManager valuation happens here on the RuneLite client thread.
     */
    private void updateRunePouchSupplies()
    {
        if (supplies == null || !supplies.isTracking()) return;
        int[] types = {
            client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1),
            client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2),
            client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_3),
            client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_4)
        };
        int[] quantities = {
            client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1),
            client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_2),
            client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_3),
            client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_4)
        };
        supplies.runePouchChanged(types, quantities);
    }

    private void completeSupplies()
    {
        if (supplies != null) supplies.finish();
    }

    private int cashOutWave()
    {
        // Claimed chest loot establishes that the latest observed combat wave
        // was finished; a run cannot cash out in the middle of combat.
        long elapsed = System.currentTimeMillis() - lastConfirmedWaveMs;
        int recentConfirmed = lastConfirmedWaveMs > 0 && elapsed >= 0 && elapsed <= 10 * 60_000 ? lastConfirmedWave : 0;
        return Math.max(recentConfirmed, Math.max(completedWave, activeWave));
    }

    private void finishCashOut(String source, int wave)
    {
        record(LedgerEvent.Type.CASH_OUT, 0, source, wave);
        completeSupplies();
        lastExitType = LedgerEvent.Type.CASH_OUT;
        lastExitMs = System.currentTimeMillis();
        lastExitWave = wave;
        exitHasLoot = false;
        terminal = true;
        active = false;
    }

    private void finishClear(String source)
    {
        record(LedgerEvent.Type.CLEAR, 0, source, 12);
        completeSupplies();
        terminal = true;
        active = false;
        completedWave = 12;
        lastClearMs = System.currentTimeMillis();
        lastExitType = LedgerEvent.Type.CLEAR;
        lastExitMs = lastClearMs;
        lastExitWave = 12;
        exitHasLoot = false;
    }

    private void finishDeath(String source)
    {
        int wave = activeWave;
        record(LedgerEvent.Type.DEATH, 0, source, wave);
        completeSupplies();
        // Recovery fee stays zero until a real payment is observed.
        // A detected gravestone payment updates THIS death row, not a second fee row.
        terminal = true;
        active = false;
        lastDeathMs = System.currentTimeMillis();
        lastExitType = LedgerEvent.Type.DEATH;
        lastExitMs = lastDeathMs;
        lastExitWave = wave;
        exitHasLoot = false;
    }

    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (!config.autoDetect()) return;
        // A completion can be delivered under ENGINE, CONSOLE or other game-message
        // categories. Parse the distinctive exact message before filtering types.
        String message = WaveMessages.normalize(Text.removeTags(event.getMessage()));
        int confirmedCompletion = WaveMessages.confirmedColosseumCompletion(message);
        if (message.contains("wave") && (message.contains("completed") || message.contains("duration")))
        {
            DIAGNOSTICS.info("Fortis wave message: type=" + event.getType()
                + " parsed=" + confirmedCompletion + " text=" + message);
        }
        if (confirmedCompletion == 0
            && event.getType() != ChatMessageType.GAMEMESSAGE
            && event.getType() != ChatMessageType.SPAM
            && event.getType() != ChatMessageType.ENGINE
            && event.getType() != ChatMessageType.CONSOLE) return;
        checkAccount();
        // Bank deduction can occur after exiting the arena; the death event
        // remains pending until its actual recovery payment is observed.
        Matcher recoveryPayment = RECOVERY_PAYMENT.matcher(message);
        if (recoveryPayment.find())
        {
            try
            {
                long gpPaid = Long.parseLong(recoveryPayment.group(1).replace(",", ""));
                long now = System.currentTimeMillis();
                String fingerprint = message + "|" + account();
                if (gpPaid > 0 && !(fingerprint.equals(lastRecoveryPaymentFingerprint)
                    && now - lastRecoveryPaymentMs < 5_000))
                {
                    boolean applied = ledger.applyRecoveryFee(account(), gpPaid, RECOVERY_WINDOW_MS);
                    DIAGNOSTICS.info("Fortis grave payment: gp=" + gpPaid + " matchedDeath=" + applied);
                    if (applied)
                    {
                        lastRecoveryPaymentFingerprint = fingerprint;
                        lastRecoveryPaymentMs = now;
                        refresh();
                    }
                }
            }
            catch (NumberFormatException ex)
            {
                DIAGNOSTICS.warning("Invalid gravestone payment amount: " + recoveryPayment.group(1));
            }
            return;
        }
        if (message.contains("colosseum") || confirmedCompletion > 0)
        {
            lastColosseumSignalMs = System.currentTimeMillis();
        }
        // Player deaths aren't guaranteed to fire ActorDeath in every
        // client transition. Use the death chat as a secondary signal, but
        // only when a Colosseum run was recently observed.
        if ((message.contains("oh dear, you are dead") || message.contains("you have died"))
            && !terminal && System.currentTimeMillis() - lastDeathMs > 15_000
            && (active || (lastColosseumSignalMs > 0
                && System.currentTimeMillis() - lastColosseumSignalMs < 20 * 60_000)))
        {
            finishDeath("Detected death message during Colosseum attempt");
            return;
        }
        if (confirmedCompletion > 0)
        {
            // The precise post-wave message is sufficient to establish a run,
            // even when the plugin did not catch the initial wave-start message.
            // completedWave is used for cash-outs; activeWave remains the last
            // observed fight until the next wave explicitly begins.
            if (!active || terminal || (confirmedCompletion == 1 && completedWave > 1))
            {
                active = true;
                terminal = false;
                activeWave = 0;
                completedWave = 0;
                // Keep pre-wave lobby expenses for this attempt. A prior run's
                // expenses were already finalized by its finish method.
                lastExitType = null;
                lastExitWave = 0;
                exitHasLoot = false;
            }
            startSuppliesIfNecessary(confirmedCompletion);
            lastConfirmedWave = confirmedCompletion;
            lastConfirmedWaveMs = System.currentTimeMillis();
            lastColosseumSignalMs = lastConfirmedWaveMs;
            DIAGNOSTICS.info("Fortis confirmed completed wave " + confirmedCompletion
                + " for " + account());
            active = true;
            activeWave = Math.max(activeWave, confirmedCompletion);
            completedWave = Math.max(completedWave, confirmedCompletion);
            // Wave 12 completed is direct proof of defeating Sol Heredit.
            // Recording this before the chest is claimed avoids a false cash-out.
            if (confirmedCompletion == 12 && !terminal)
            {
                finishClear("Confirmed wave 12 completion (Sol Heredit)");
            }
            refresh();
            return;
        }
        int wave = WaveMessages.wave(message);
        // Only trust wave numbers when the message explicitly mentions the Colosseum,
        // or when an existing run is active. Avoid counting other minigames' waves.
        if (wave > 0 && (message.contains("colosseum") || active || (message.startsWith("wave: 1") && !terminal)))
        {
            if (wave == 1 && (activeWave == 0 || activeWave > 1 || terminal))
            {
                active = true;
                terminal = false;
                // Do not discard expenses accumulated in the lobby before wave 1.
                completedWave = 0;
                lastExitType = null;
                exitHasLoot = false;
            }
            if (wave > activeWave && activeWave > 0 && active)
            {
                // Reaching wave N shows the preceding wave was survived.
                completedWave = Math.max(completedWave, wave - 1);
            }
            startSuppliesIfNecessary(wave);
            activeWave = wave;
            lastColosseumSignalMs = System.currentTimeMillis();
            active = true;
            if (WaveMessages.completed(message))
            {
                completedWave = Math.max(completedWave, wave);
            }
            refresh();
        }
        boolean fullClearMessage = (message.contains("sol heredit") && (message.contains("defeated") || message.contains("vanquished")))
            || message.contains("completed the fortis colosseum")
            || message.contains("conquered the colosseum");
        if (fullClearMessage && !terminal && System.currentTimeMillis() - lastClearMs > 15_000)
        {
            finishClear("Detected Colosseum completion message");
        }
    }

    @Subscribe public void onActorDeath(ActorDeath event)
    {
        checkAccount();
        if (!config.autoDetect() || terminal || client.getLocalPlayer() == null) return;
        if (!active && !(lastColosseumSignalMs > 0
            && System.currentTimeMillis() - lastColosseumSignalMs < 20 * 60_000)) return;
        if (event.getActor() != client.getLocalPlayer()) return;
        if (System.currentTimeMillis() - lastDeathMs > 15_000)
        {
            finishDeath("Detected player death during active attempt");
        }
    }

    @Subscribe public void onLootReceived(LootReceived event)
    {
        if (!config.autoDetect()) return;
        checkAccount();
        String source = event.getName();
        if (source == null || !source.toLowerCase(Locale.ROOT).contains("colosseum")) return;
        long value = 0;
        StringBuilder fingerprint = new StringBuilder(source).append('|');
        for (ItemStack item : event.getItems())
        {
            if (item.getQuantity() > 0)
            {
                value += (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
                fingerprint.append(item.getId()).append(':').append(item.getQuantity()).append(';');
            }
        }
        if (value <= 0) return;
        long now = System.currentTimeMillis();
        String key = fingerprint.toString();
        if (key.equals(lastLootFingerprint) && now - lastLootMs < 5_000) return;

        LedgerEvent.Type outcome;
        int wave;
        boolean recentExit = lastExitType != null && now - lastExitMs < 300_000;
        if (recentExit && (lastExitType == LedgerEvent.Type.CLEAR || lastExitType == LedgerEvent.Type.CASH_OUT))
        {
            outcome = lastExitType;
            wave = Math.max(lastExitWave, cashOutWave());
        }
        else
        {
            // Only a completed wave 12 proves a Sol kill. Merely entering
            // wave 12 must not be classified as a clear.
            boolean solCompleted = completedWave >= 12
                || (lastConfirmedWave == 12 && lastConfirmedWaveMs > 0
                    && now - lastConfirmedWaveMs >= 0 && now - lastConfirmedWaveMs < 10 * 60_000);
            wave = solCompleted ? 12 : cashOutWave();
            if (solCompleted)
            {
                outcome = LedgerEvent.Type.CLEAR;
                finishClear("Confirmed wave 12 before Colosseum loot");
            }
            else
            {
                outcome = LedgerEvent.Type.CASH_OUT;
                finishCashOut("Inferred early cash-out from Colosseum loot", wave);
            }
        }
        DIAGNOSTICS.info("Fortis chest loot: source=" + source + " gp=" + value
            + " wave=" + wave + " confirmed=" + lastConfirmedWave
            + " completed=" + completedWave + " active=" + activeWave
            + " account=" + account());
        String note = "Claimed Colosseum loot (GE estimate; " + source + ")";
        if (!ledger.creditRecentExit(outcome, account(), value, wave, note))
        {
            record(outcome, value, note, wave);
        }
        refresh();
        exitHasLoot = true;
        lastLootFingerprint = key;
        lastLootMs = now;
    }
}

package com.fortisprofit;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.NumberFormat;
import java.util.Locale;

/** Abbreviated presentation only. The ledger and CSV always use exact integer GP. */
final class GpFormat
{
    private GpFormat() {}

    static String shortGp(long amount)
    {
        BigDecimal absolute = BigDecimal.valueOf(amount).abs();
        String prefix = amount < 0 ? "-" : "";
        if (absolute.compareTo(BigDecimal.valueOf(999_995_000L)) >= 0)
        {
            return prefix + abbreviated(absolute, 1_000_000_000L, 2) + "B";
        }
        if (absolute.compareTo(BigDecimal.valueOf(999_950L)) >= 0)
        {
            return prefix + abbreviated(absolute, 1_000_000L, 2) + "M";
        }
        if (absolute.compareTo(BigDecimal.valueOf(1_000L)) >= 0)
        {
            return prefix + abbreviated(absolute, 1_000L, 1) + "K";
        }
        return Long.toString(amount);
    }

    private static String abbreviated(BigDecimal amount, long divisor, int places)
    {
        return amount.divide(BigDecimal.valueOf(divisor), places, RoundingMode.HALF_UP)
            .stripTrailingZeros().toPlainString();
    }

    static String exactGp(long amount)
    {
        return NumberFormat.getIntegerInstance(Locale.US).format(amount) + " GP";
    }
}

package com.fortisprofit;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;

final class LedgerEvent {
    enum Type { CLEAR, DEATH, CASH_OUT, LOOT, CLEAR_LOOT, CASH_OUT_LOOT, DEATH_FEE, SUPPLIES, ADJUSTMENT, QUIVER_TURN_IN }

    String account;
    String timestamp;
    Type type;
    long gp;
    String note;
    // -1 means adjustment, 0 means unknown; missing in older v0.2/v0.3 JSON and defaults safely to 0.
    int wave;

    LedgerEvent(String account, Type type, long gp, String note) {
        this(account, type, gp, note, 0);
    }

    LedgerEvent(String account, Type type, long gp, String note, int wave) {
        this.account = account;
        this.timestamp = Instant.now().toString();
        this.type = type;
        this.gp = gp;
        this.note = note;
        this.wave = wave;
    }

    LocalDate date(ZoneId zone) { return Instant.parse(timestamp).atZone(zone).toLocalDate(); }
}

package com.fortisprofit;

import com.google.gson.Gson;
import java.io.Reader;
import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.util.Filepath;

final class LedgerStore
{
    private final Gson gson;
    private final Filepath directory;
    private final Filepath file;
    private final List<LedgerEvent> events = new ArrayList<>();

    LedgerStore(Gson gson, Filepath directory)
    {
        this.gson = gson;
        this.directory = directory;
        this.file = directory.joinSegment("ledger.json");
    }

    /** Reload without changing the current in-memory ledger unless parsing succeeds. */
    synchronized int load()
    {
        // A brand-new installation may not have a ledger file yet.
        if (!file.isFile()) return events.size();
        return reload();
    }

    synchronized int reload()
    {
        if (!file.isFile())
        {
            throw new IllegalStateException("Ledger file not found: " + file);
        }
        try (Reader reader = file.openBufferedReader())
        {
            List<LedgerEvent> loaded = parseEntries(gson, reader);
            events.clear();
            events.addAll(loaded);
            return events.size();
        }
        catch (Exception ex)
        {
            throw new IllegalStateException("Could not read ledger " + file + ". Existing history retained.", ex);
        }
    }

    /** Parse in isolation so errors never erase the current ledger. */
    static List<LedgerEvent> parseEntries(Gson gson, Reader reader)
    {
        LedgerEvent[] found = gson.fromJson(reader, LedgerEvent[].class);
        if (found == null)
        {
            throw new IllegalArgumentException("Expected a JSON array of ledger entries, not null");
        }
        List<LedgerEvent> loaded = new ArrayList<>();
        for (LedgerEvent event : found)
        {
            if (event == null)
            {
                throw new IllegalArgumentException("Ledger contains a null entry");
            }
            // Some v1.3.3 quiver records were serialized without a type.
            if (event.type == null && event.note != null
                && event.note.startsWith("Dizana's quiver exchanged for 4,000 Sunfire splinters"))
            {
                event.type = LedgerEvent.Type.ADJUSTMENT;
            }
            if (event.type == null || event.account == null || event.account.trim().isEmpty()
                || event.timestamp == null || event.wave < -1 || event.wave > 12)
            {
                throw new IllegalArgumentException("Ledger entry has missing or invalid fields");
            }
            try { java.time.Instant.parse(event.timestamp); }
            catch (Exception ex) { throw new IllegalArgumentException("Invalid ledger timestamp", ex); }
            loaded.add(event);
        }
        // Preserve older exit/loot records without rewriting their file on reload.
        consolidateLegacyPairs(loaded);
        return loaded;
    }

    /** Consolidate v0.4 cash-out/clear event and corresponding loot into one outcome row. */
    private static void consolidateLegacyPairs(List<LedgerEvent> entries)
    {
        List<LedgerEvent> remove = new ArrayList<>();
        for (LedgerEvent loot : entries)
        {
            LedgerEvent.Type outcomeType = loot.type == LedgerEvent.Type.CASH_OUT_LOOT
                ? LedgerEvent.Type.CASH_OUT : loot.type == LedgerEvent.Type.CLEAR_LOOT
                ? LedgerEvent.Type.CLEAR : null;
            if (outcomeType == null) continue;
            LedgerEvent match = null;
            long bestDelta = Long.MAX_VALUE;
            for (LedgerEvent outcome : entries)
            {
                if (outcome.type != outcomeType || !java.util.Objects.equals(outcome.account, loot.account)
                    || outcome.gp != 0 || remove.contains(outcome)) continue;
                try
                {
                    long delta = Math.abs(java.time.Instant.parse(outcome.timestamp).toEpochMilli()
                        - java.time.Instant.parse(loot.timestamp).toEpochMilli());
                    if (delta <= 300_000 && delta < bestDelta) { match = outcome; bestDelta = delta; }
                }
                catch (Exception ignored) { }
            }
            if (match != null)
            {
                match.gp += loot.gp;
                if (match.wave == 0) match.wave = loot.wave;
                match.note = "Consolidated exit and claimed loot (legacy): " + loot.note;
                remove.add(loot);
            }
        }
        entries.removeAll(remove);
        // Standalone old loot classified as a successful exit is a complete outcome itself.
        for (LedgerEvent e : entries)
        {
            if (e.type == LedgerEvent.Type.CASH_OUT_LOOT) e.type = LedgerEvent.Type.CASH_OUT;
            if (e.type == LedgerEvent.Type.CLEAR_LOOT) e.type = LedgerEvent.Type.CLEAR;
        }
    }

    /** Add GP to an existing exit, avoiding a second ledger row. */
    synchronized boolean creditRecentExit(LedgerEvent.Type type, String account, long gp, int wave, String note)
    {
        long now = System.currentTimeMillis();
        for (int i = events.size() - 1; i >= 0; i--)
        {
            LedgerEvent entry = events.get(i);
            if (entry.type != type || !java.util.Objects.equals(account, entry.account)) continue;
            try
            {
                if (now - java.time.Instant.parse(entry.timestamp).toEpochMilli() > 300_000) continue;
            }
            catch (Exception ignored) { continue; }
            entry.gp += gp;
            if (entry.wave == 0) entry.wave = wave;
            entry.note = note;
            save();
            return true;
        }
        return false;
    }

    /** Apply an actual gravestone bank payment to the latest unpaid death.
     * Reject stale/ambiguous payments rather than changing unrelated P&L.
     * Older v1.1 DEATH rows are eligible as long as they're still at zero.
     */
    synchronized boolean applyRecoveryFee(String account, long gpPaid, long maxAgeMs)
    {
        if (gpPaid <= 0) return false;
        long now = System.currentTimeMillis();
        for (int i = events.size() - 1; i >= 0; i--)
        {
            LedgerEvent event = events.get(i);
            if (event.type != LedgerEvent.Type.DEATH || event.gp != 0
                || !java.util.Objects.equals(event.account, account)
                || (event.note != null && event.note.contains("[recovery fee recorded]"))) continue;
            long elapsed;
            try { elapsed = now - java.time.Instant.parse(event.timestamp).toEpochMilli(); }
            catch (Exception ex) { continue; }
            if (elapsed < 0 || elapsed > maxAgeMs) continue;
            event.gp = -gpPaid;
            event.note = (event.note == null ? "" : event.note) + " [recovery fee recorded]";
            save();
            return true;
        }
        return false;
    }

    synchronized List<LedgerEvent> list() { return new ArrayList<>(events); }
    synchronized void add(LedgerEvent event) { events.add(event); save(); }
    synchronized void delete(LedgerEvent event) { if (events.remove(event)) save(); }

    /** Modify a saved entry without changing its original timestamp or account. */
    synchronized boolean update(LedgerEvent event, LedgerEvent.Type type, long gp, int wave, String note)
    {
        if (event == null || type == null || !events.contains(event) || wave < -1 || wave > 12)
        {
            return false;
        }
        event.type = type;
        event.gp = gp;
        event.wave = wave;
        event.note = note == null ? "" : note;
        save();
        return true;
    }

    private void save()
    {
        try
        {
            directory.createDirectories();
            Filepath temp = directory.joinSegment("ledger.json.tmp");
            temp.write(gson.toJson(events));
            try
            {
                temp.moveTo(file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            }
            catch (java.nio.file.AtomicMoveNotSupportedException ex)
            {
                temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException ex) { throw new IllegalStateException("Could not save Fortis ledger: " + file, ex); }
    }
}

package com.fortisprofit;

import java.util.Locale;
import net.runelite.api.ItemID;

/** Canonical label/item key for 1-4-dose potions in the Current Run grid.
 * Uses a reviewable, explicit mapping rather than reflection on ItemID fields.
 */
final class PotionGrouping
{
    private PotionGrouping() { }

    static String fullName(String doseName)
    {
        return doseName.replaceFirst("\\([1-4]\\)$", "(4)");
    }

    static String fieldName(String fullName)
    {
        return fullName.toUpperCase(Locale.ROOT).replaceAll("[^A-Z0-9]+", "_")
            .replaceFirst("_4_$", "4").replaceFirst("_4$", "4");
    }

    /** Explicitly known 4-dose variants. Unknowns return -1 and retain
     * WaveSupplyTracker's existing dose-price fallback behavior.
     */
    static int fullDoseId(String fullName)
    {
        switch (fullName.toLowerCase(Locale.ROOT))
        {
            case "saradomin brew(4)": return ItemID.SARADOMIN_BREW4;
            case "super restore(4)": return ItemID.SUPER_RESTORE4;
            case "prayer potion(4)": return ItemID.PRAYER_POTION4;
            case "ranging potion(4)": return ItemID.RANGING_POTION4;
            case "magic potion(4)": return ItemID.MAGIC_POTION4;
            case "stamina potion(4)": return ItemID.STAMINA_POTION4;
            case "super combat potion(4)": return ItemID.SUPER_COMBAT_POTION4;
            case "bastion potion(4)": return ItemID.BASTION_POTION4;
            case "battlemage potion(4)": return ItemID.BATTLEMAGE_POTION4;
            case "divine ranging potion(4)": return ItemID.DIVINE_RANGING_POTION4;
            case "divine magic potion(4)": return ItemID.DIVINE_MAGIC_POTION4;
            case "divine super combat potion(4)": return ItemID.DIVINE_SUPER_COMBAT_POTION4;
            case "super attack(4)": return ItemID.SUPER_ATTACK4;
            case "super strength(4)": return ItemID.SUPER_STRENGTH4;
            case "super defence(4)": return ItemID.SUPER_DEFENCE4;
            case "attack potion(4)": return ItemID.ATTACK_POTION4;
            case "strength potion(4)": return ItemID.STRENGTH_POTION4;
            case "defence potion(4)": return ItemID.DEFENCE_POTION4;
            case "restore potion(4)": return ItemID.RESTORE_POTION4;
            case "sanfew serum(4)": return ItemID.SANFEW_SERUM4;
            case "super energy(4)": return ItemID.SUPER_ENERGY4;
            case "energy potion(4)": return ItemID.ENERGY_POTION4;
            case "antifire potion(4)": return ItemID.ANTIFIRE_POTION4;
            case "extended antifire(4)": return ItemID.EXTENDED_ANTIFIRE4;
            case "super antifire potion(4)": return ItemID.SUPER_ANTIFIRE_POTION4;
            case "extended super antifire(4)": return ItemID.EXTENDED_SUPER_ANTIFIRE4;
            default: return -1;
        }
    }
}

package com.fortisprofit;

/** Compares rune-pouch slots without mistaking refills or slot swaps for casts. */
final class RunePouchDiff
{
    private RunePouchDiff() { }

    /** A change of rune type is not enough evidence of consumption.
     * The slot's type may become zero when the last rune is used.
     * Restrict one observed decrement to 20 runes to avoid counting withdrawals.
     */
    static int consumed(int oldType, int oldQuantity, int newType, int newQuantity)
    {
        if (oldType <= 0 || oldQuantity <= 0 || newQuantity >= oldQuantity) return 0;
        if (newType != oldType && !(newType == 0 && newQuantity == 0)) return 0;
        int loss = oldQuantity - newQuantity;
        return loss <= 20 ? loss : 0;
    }
}

package com.fortisprofit;

/**
 * Accumulates all detected supplies for one Colosseum attempt, including
 * preparation in the lobby. Persist one Adj. expense when the run finishes.
 */
final class WaveCostAccumulator
{
    interface Sink { void record(int wave, long cost, String note); }
    private final Sink sink;
    private long cost;
    private int units;

    WaveCostAccumulator(Sink sink) { this.sink = sink; }

    void begin(int startWave) { reset(); }

    void add(long gp, int quantity)
    {
        if (gp > 0 && quantity > 0)
        {
            cost += gp;
            units += quantity;
        }
    }

    // Wave changes must not create expense entries or clear accrued lobby costs.
    void changeWave(int nextWave) { }

    void finish()
    {
        if (cost > 0)
        {
            sink.record(-1, cost, "Automatically tracked supplies (" + units + " units; lobby and arena)");
        }
        reset();
    }

    void reset()
    {
        cost = 0;
        units = 0;
    }
}

package com.fortisprofit;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Conservative parser of Colosseum-related game messages, not a verified game-state varbit. */
final class WaveMessages
{
    private static final Pattern WAVE = Pattern.compile("\\bwave\\s*(?:number\\s*)?[:#-]?\\s*(1[0-2]|[1-9])(?:\\s*/\\s*12)?\\b");
    private static final Pattern COMPLETED = Pattern.compile(
        "(?:\\bcompleted\\s+(?:the\\s+)?wave\\b)|(?:\\b(?:wave\\s*(?:number\\s*)?[:#-]?\\s*(?:1[0-2]|[1-9]))\\s+(?:is\\s+)?(?:complete|completed|cleared|finished)\\b)");
    // The in-game reward message has no Colosseum name, so recognize its distinctive
    // full text rather than requiring the player to have an active tracked attempt.
    private static final Pattern COLOSSEUM_WAVE_COMPLETED = Pattern.compile(
        "\\bwave\\s+(1[0-2]|[1-9])\\s+completed!\\s+wave\\s+duration:\\s*\\d{1,2}:\\d{2}(?::\\d{2})?\\b",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern OSRS_COLOR_CODES = Pattern.compile("@[a-zA-Z0-9_]+@");
    private WaveMessages() { }

    static String normalize(String message)
    {
        if (message == null) return "";
        return OSRS_COLOR_CODES.matcher(message).replaceAll("")
            .toLowerCase(Locale.ROOT).trim();
    }

    static int confirmedColosseumCompletion(String message)
    {
        Matcher matcher = COLOSSEUM_WAVE_COMPLETED.matcher(normalize(message));
        return matcher.find() ? Integer.parseInt(matcher.group(1)) : 0;
    }

    static int wave(String message)
    {
        Matcher match = WAVE.matcher(message.toLowerCase(Locale.ROOT));
        if (!match.find()) return 0;
        return Integer.parseInt(match.group(1));
    }

    static boolean completed(String message)
    {
        return COMPLETED.matcher(message.toLowerCase(Locale.ROOT)).find();
    }
}

package com.fortisprofit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.Item;
import net.runelite.api.ItemID;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

/**
 * Restricted, Colosseum-only inventory/equipment consumption tracker.
 * Costs across the lobby and all waves are finalized as one Adj. ledger row.
 *
 * Inspired by the inventory comparison approach in SuppliesTrackerExternal,
 * Copyright (c) 2019 Dozer, BSD-2-Clause (see THIRD_PARTY_NOTICES.md).
 * Uses deliberately conservative detection. Rune pouch changes are tracked
 * via varbits; charged weapons and blowpipe shots use attack/projectile estimates.
 * Direct ammunition losses and Dizana's quiver stack changes are recorded.
 * Inventory swaps are never assumed to be consumed ammunition.
 * All ItemManager calls must run on the RuneLite client thread.
 */
final class WaveSupplyTracker
{
    interface Sink { void record(int wave, long gpCost, String description); }

    private final ItemManager itemManager;
    private final Sink sink;
    private final Runnable onChange;
    static final int DEMON_TEAR_ID = 31111;
    // Formulas sourced from SuppliesTrackerExternal, updated to the current
    // OSRS scythe charge recipe (2 blood runes + 1/100 vial per charge).
    static final int SCYTHE_ICON_ID = ItemID.SCYTHE_OF_VITUR;
    static final int SHADOW_ICON_ID = ItemID.TUMEKENS_SHADOW;
    static final int VENATOR_BOW_ICON_ID = ItemID.VENATOR_BOW;


    static final class ItemUsage
    {
        final int itemId;
        final String name;
        final int count;
        final long cost;
        ItemUsage(int itemId, String name, int count, long cost)
        {
            this.itemId = itemId;
            this.name = name;
            this.count = count;
            this.cost = cost;
        }
    }

    private final Map<Integer, ItemUsage> usage = new HashMap<>();
    private long currentCost;
    private final int[] pouchTypes = new int[4];
    private final int[] pouchQuantities = new int[4];
    private boolean pouchInitialized;
    private Map<Integer, Integer> inventory = new HashMap<>();
    private int ammoId = -1;
    private int ammoQuantity;
    private int quiverAmmoId = -1;
    private int quiverAmmoQuantity;
    private int blowpipeDartId = -1;
    private int pendingBlowpipeDarts;
    private final AmmoCostEstimator blowpipeCosts = new AmmoCostEstimator();
    private boolean tracking;
    private int wave;
    private final WaveCostAccumulator accumulator;
    private int pendingConsumedId = -1;
    private long pendingAt;

    WaveSupplyTracker(ItemManager itemManager, Sink sink, Runnable onChange)
    {
        this.itemManager = itemManager;
        this.sink = Objects.requireNonNull(sink);
        this.onChange = Objects.requireNonNull(onChange);
        this.accumulator = new WaveCostAccumulator(sink::record);
    }

    List<ItemUsage> currentItems()
    {
        List<ItemUsage> items = new ArrayList<>(usage.values());
        items.sort((a, b) -> Long.compare(b.cost, a.cost));
        return Collections.unmodifiableList(items);
    }

    long currentCost() { return currentCost; }

    boolean isTracking() { return tracking; }

    void begin(int wave, ItemContainer inventoryContainer, ItemContainer equipmentContainer)
    {
        reset();
        tracking = true;
        this.wave = wave == -1 ? -1 : Math.max(1, Math.min(12, wave));
        accumulator.begin(this.wave);
        inventory = countItems(inventoryContainer);
        snapshotAmmo(equipmentContainer);
        quiverAmmoId = -1;
        quiverAmmoQuantity = 0;
    }

    void reset()
    {
        boolean changed = tracking || !usage.isEmpty() || currentCost != 0;
        tracking = false;
        inventory.clear();
        ammoId = -1;
        ammoQuantity = 0;
        quiverAmmoId = -1;
        quiverAmmoQuantity = 0;
        blowpipeDartId = -1;
        pendingBlowpipeDarts = 0;
        blowpipeCosts.reset();
        wave = 0;
        accumulator.reset();
        pendingConsumedId = -1;
        usage.clear();
        currentCost = 0;
        pouchInitialized = false;
        java.util.Arrays.fill(pouchTypes, 0);
        java.util.Arrays.fill(pouchQuantities, 0);
        if (changed) onChange.run();
    }

    void changeWave(int wave)
    {
        if (!tracking || wave < 1 || wave > 12) return;
        if (wave != this.wave)
        {
            accumulator.changeWave(wave);
            this.wave = wave;
        }
    }

    void finish()
    {
        if (tracking) accumulator.finish();
        reset();
    }

    /** Only count an eaten food or drunk potion if an action occurred shortly before its disappearance. */
    void onMenuOption(String option, int itemId)
    {
        if (!tracking || itemId <= 0 || option == null) return;
        String action = option.toLowerCase(Locale.ROOT);
        if (action.equals("eat") || action.equals("drink"))
        {
            pendingConsumedId = itemId;
            pendingAt = System.currentTimeMillis();
        }
    }

    void inventoryChanged(ItemContainer container)
    {
        if (!tracking) return;
        Map<Integer, Integer> next = countItems(container);
        boolean pendingFresh = System.currentTimeMillis() - pendingAt < 2_500L;
        for (Map.Entry<Integer, Integer> previous : inventory.entrySet())
        {
            int id = previous.getKey();
            int lost = previous.getValue() - next.getOrDefault(id, 0);
            if (lost <= 0) continue;
            String name = itemName(id);
            if (name.endsWith(" rune"))
            {
                // Inventory rune consumption; withdrawing/placing into a pouch can
                // look the same, so pricing this category is explicitly best-effort.
                accrue(id, name, lost, price(id));
            }
            else if (id == pendingConsumedId && pendingFresh)
            {
                int dose = potionDoses(name);
                if (dose > 0)
                {
                    // Every dose (whether drawn from (1), (2), (3), or (4))
                    // is valued at exactly 1/4 of the same full potion.
                    String canonical = PotionGrouping.fullName(name);
                    int canonicalId = PotionGrouping.fullDoseId(canonical);
                    boolean knownFullDose = canonicalId > 0;
                    long fullPrice = knownFullDose ? price(canonicalId) : 0;
                    // Known potions are valued at a quarter of the 4-dose price.
                    // For an unknown variant, use the observed dose variant's
                    // price divided by its remaining doses as a fallback.
                    long each = Math.round((double) (fullPrice > 0 ? fullPrice : price(id))
                        / (fullPrice > 0 ? 4 : dose));
                    accrue(knownFullDose ? canonicalId : id, canonical, Math.min(lost, 1), each);
                }
                else
                {
                    accrue(id, name, Math.min(lost, 1), price(id));
                }
                pendingConsumedId = -1;
            }
        }
        inventory = next;
    }

    void equipmentChanged(ItemContainer equipment)
    {
        if (!tracking || equipment == null) return;
        // RuneLite's equipment ammo slot is index 13.
        Item[] equipped = equipment.getItems();
        Item ammo = equipped.length > 13 ? equipped[13] : null;
        int id = ammo == null ? -1 : ammo.getId();
        int quantity = ammo == null ? 0 : Math.max(0, ammo.getQuantity());
        if (id >= 0 && id == ammoId && ammoQuantity > quantity && isAmmo(itemName(id)))
        {
            int lost = ammoQuantity - quantity;
            // Include 2-shot weapons, but exclude bulk inventory moves.
            if (lost <= 2) accrue(id, itemName(id), lost, price(id));
        }
        else if ((id < 0 || id != ammoId) && ammoId > 0 && ammoQuantity <= 2
            && isAmmo(itemName(ammoId)))
        {
            // Last arrows fired: the stack can disappear completely.
            accrue(ammoId, itemName(ammoId), ammoQuantity, price(ammoId));
        }
        ammoId = id;
        ammoQuantity = quantity;
    }

    /** Rune pouch quantities and types come from RuneLite varbits, unlike inventory runes.
     * Snapshot first; subsequent decrements are valued as consumed runes.
     * Inspired by SuppliesTrackerExternal's RunePouch/Runes mapping.
     */
    void runePouchChanged(int[] types, int[] quantities)
    {
        if (!tracking || types == null || quantities == null || types.length != 4 || quantities.length != 4) return;
        for (int i = 0; i < 4; i++)
        {
            int type = types[i];
            int amount = Math.max(0, quantities[i]);
            if (pouchInitialized)
            {
                int consumed = RunePouchDiff.consumed(pouchTypes[i], pouchQuantities[i], type, amount);
                int runeId = runePouchItemId(pouchTypes[i]);
                if (consumed > 0 && runeId > 0)
                    accrue(runeId, itemName(runeId), consumed, price(runeId));
            }
            pouchTypes[i] = type;
            pouchQuantities[i] = amount;
        }
        pouchInitialized = true;
    }

    /** Rune-pouch type codes from SuppliesTrackerExternal's Runes enum. */
    static int runePouchItemId(int type)
    {
        switch (type)
        {
            case 1: return net.runelite.api.gameval.ItemID.AIRRUNE;
            case 2: return net.runelite.api.gameval.ItemID.WATERRUNE;
            case 3: return net.runelite.api.gameval.ItemID.EARTHRUNE;
            case 4: return net.runelite.api.gameval.ItemID.FIRERUNE;
            case 5: return net.runelite.api.gameval.ItemID.MINDRUNE;
            case 6: return net.runelite.api.gameval.ItemID.CHAOSRUNE;
            case 7: return net.runelite.api.gameval.ItemID.DEATHRUNE;
            case 8: return net.runelite.api.gameval.ItemID.BLOODRUNE;
            case 9: return net.runelite.api.gameval.ItemID.COSMICRUNE;
            case 10: return net.runelite.api.gameval.ItemID.NATURERUNE;
            case 11: return net.runelite.api.gameval.ItemID.LAWRUNE;
            case 12: return net.runelite.api.gameval.ItemID.BODYRUNE;
            case 13: return net.runelite.api.gameval.ItemID.SOULRUNE;
            case 14: return net.runelite.api.gameval.ItemID.ASTRALRUNE;
            case 15: return net.runelite.api.gameval.ItemID.MISTRUNE;
            case 16: return net.runelite.api.gameval.ItemID.MUDRUNE;
            case 17: return net.runelite.api.gameval.ItemID.DUSTRUNE;
            case 18: return net.runelite.api.gameval.ItemID.LAVARUNE;
            case 19: return net.runelite.api.gameval.ItemID.STEAMRUNE;
            case 20: return net.runelite.api.gameval.ItemID.SMOKERUNE;
            case 21: return net.runelite.api.gameval.ItemID.WRATHRUNE;
            case 22: return net.runelite.api.gameval.ItemID.SUNFIRERUNE;
            case 23: return net.runelite.api.gameval.ItemID.AETHERRUNE;
            default: return -1;
        }
    }

    /** Track ammunition stored inside Dizana's quiver via RuneLite's quiver varps.
     * The equipment ammo slot does not reflect these counts.
     * Assumes losses of 1-2 are fired, rather than a manual withdrawal.
     */
    void quiverChanged(int id, int quantity)
    {
        if (!tracking) return;
        quantity = Math.max(0, quantity);
        if (id == quiverAmmoId && id > 0 && quiverAmmoQuantity > quantity)
        {
            int lost = quiverAmmoQuantity - quantity;
            if (lost <= 2 && isAmmo(itemName(id))) accrue(id, itemName(id), lost, price(id));
        }
        else if (id < 0 && quiverAmmoId > 0 && quiverAmmoQuantity > 0
            && quiverAmmoQuantity <= 2 && isAmmo(itemName(quiverAmmoId)))
        {
            accrue(quiverAmmoId, itemName(quiverAmmoId), quiverAmmoQuantity, price(quiverAmmoId));
        }
        quiverAmmoId = id;
        quiverAmmoQuantity = quantity;
    }

    void snapshotQuiver(int id, int count)
    {
        quiverAmmoId = id;
        quiverAmmoQuantity = Math.max(0, count);
    }

    /** The projectile identifies the dart type held internally by Blowpipe. */
    void blowpipeDartObserved(int dartId)
    {
        if (!tracking || dartId <= 0) return;
        blowpipeDartId = dartId;
        if (pendingBlowpipeDarts > 0)
        {
            accrue(blowpipeDartId, itemName(blowpipeDartId), pendingBlowpipeDarts,
                price(blowpipeDartId));
            pendingBlowpipeDarts = 0;
        }
    }

    /** Charge scales from observed shots even before the dart type is known.
     * Dart type is learned from the player's projectile and retroactively
     * applied to accumulated expected dart losses.
     */
    void blowpipeShot(double dartLossRate)
    {
        if (!tracking) return;
        int[] lost = blowpipeCosts.shot(dartLossRate);
        if (lost[0] > 0)
        {
            if (blowpipeDartId > 0)
                accrue(blowpipeDartId, itemName(blowpipeDartId), lost[0], price(blowpipeDartId));
            else
                pendingBlowpipeDarts += lost[0];
        }
        if (lost[1] > 0)
            accrue(ItemID.ZULRAHS_SCALES, "Zulrah's scales", lost[1], price(ItemID.ZULRAHS_SCALES));
    }

    /** Eye of Ayak: always value each observed cast as one Demon Tear. */
    void ayakCast()
    {
        if (!tracking) return;
        accrue(DEMON_TEAR_ID, "Demon tear (Eye of Ayak)", 1, price(DEMON_TEAR_ID));
    }

    /**
     * Estimated scythe charge usage: animation count, rather than verified
     * successful hits. Scythe only consumes charges if at least one hit damages.
     * Keep the estimate visible in the Current Run item tile.
     */
    void scytheAttack()
    {
        if (!tracking) return;
        long blood = price(ItemID.BLOOD_RUNE);
        long vial = price(ItemID.VIAL_OF_BLOOD_22446);
        if (blood <= 0 || vial <= 0) return;
        // Avoid per-hit integer truncation by recording a rounded total per hit.
        long each = ChargedWeaponCosts.scythe(blood, vial);
        accrue(SCYTHE_ICON_ID, "Scythe charges (attack estimate)", 1, each);
    }

    /** Tumeken's Shadow: two soul and five chaos runes per charged cast. */
    void shadowCast()
    {
        if (!tracking) return;
        long soul = price(ItemID.SOUL_RUNE);
        long chaos = price(ItemID.CHAOS_RUNE);
        if (soul <= 0 || chaos <= 0) return;
        accrue(SHADOW_ICON_ID, "Tumeken's shadow charges", 1, ChargedWeaponCosts.shadow(soul, chaos));
    }

    /** Venator Bow: one Ancient Essence per fired arrow, never per ricochet.
     * Arrow consumption is tracked separately by quiver/equipment changes.
     */
    void venatorBowAttack()
    {
        if (!tracking) return;
        accrue(VENATOR_BOW_ICON_ID, "Venator bow charges (Ancient essence)",
            1, ChargedWeaponCosts.venatorBow(price(ItemID.ANCIENT_ESSENCE)));
    }

    private void accrue(int id, String name, int amount, long unitPrice)
    {
        if (amount <= 0 || unitPrice <= 0) return;
        long gp = unitPrice * (long) amount;
        accumulator.add(gp, amount);
        currentCost += gp;
        ItemUsage old = usage.get(id);
        usage.put(id, new ItemUsage(id, name, (old == null ? 0 : old.count) + amount,
            (old == null ? 0 : old.cost) + gp));
        onChange.run();
    }

    private long price(int id)
    {
        return itemManager == null ? 0 : Math.max(0, itemManager.getItemPrice(id));
    }

    private String itemName(int id)
    {
        return itemManager == null ? "" : itemManager.getItemComposition(id).getName().toLowerCase(Locale.ROOT);
    }

    private static int potionDoses(String name)
    {
        if (name.endsWith("(1)")) return 1;
        if (name.endsWith("(2)")) return 2;
        if (name.endsWith("(3)")) return 3;
        if (name.endsWith("(4)")) return 4;
        return 0;
    }

    private static boolean isAmmo(String name)
    {
        return name.contains(" arrow") || name.endsWith("arrow") || name.contains(" bolt")
            || name.endsWith("bolts") || name.contains(" dart") || name.endsWith("darts");
    }

    private void snapshotAmmo(ItemContainer equipment)
    {
        if (equipment == null) return;
        Item[] slots = equipment.getItems();
        Item ammo = slots.length > 13 ? slots[13] : null;
        ammoId = ammo == null ? -1 : ammo.getId();
        ammoQuantity = ammo == null ? 0 : Math.max(0, ammo.getQuantity());
    }

    private static Map<Integer, Integer> countItems(ItemContainer container)
    {
        Map<Integer, Integer> quantities = new HashMap<>();
        if (container == null) return quantities;
        for (Item item : container.getItems())
        {
            if (item != null && item.getId() > 0 && item.getQuantity() > 0)
                quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        return quantities;
    }
}

